    line(X(xs), Y(bot), X(xs), Y(top) - 40, 2.6); arrow(X(xs), Y(top) - 52, -Math.PI / 2);
    for (var t = Math.ceil(xs); t <= xe + 1e-9; t++) { var big = t % 2 === 0; line(X(t), Y(bot) - (big ? 12 : 7), X(t), Y(bot) + (big ? 12 : 7), 2); if (big) txt(String(t), X(t), Y(bot) + 36, { sz: 27 }); }
    txt("T, ч", X(xe) + 46, Y(bot) + 36, { it: true, sz: 28 });
