    txt("0 — поверхность моря на карте (НГ)", X(xs) + 10, Y(bot) + 78, { al: "left", sz: 22, col: "#333" });
    c.save(); c.beginPath(); c.rect(X(xs) - 2, Y(top) - 60, X(xe) - X(xs) + 4, Y(bot) - Y(top) + 62); c.clip();
