            lines: cr.map(function (c) { var B = Math.abs(c.b.h - c.a.h); return (c.up ? "Рост: " : "Падение: ") + T(c.a.t) + " " + f(c.a.h, 1) + " м → " + T(c.b.t) + " " + f(c.b.h, 1) + " м;  B = " + f(B, 1) + " м, F = " + f(Math.abs(hp - (c.up ? c.a.h : c.b.h)) / B, 2) + " → T = " + T(c.t); }),
