      [46, 66.5].forEach(function (x) { c.strokeStyle = "#c9a227"; c.lineWidth = 6; c.beginPath(); c.moveTo(X(x), Y(20)); c.lineTo(X(x), Y(31)); c.stroke(); c.lineWidth = 4; c.beginPath(); c.moveTo(X(x), Y(30)); c.lineTo(X(x + 9), Y(24)); c.stroke(); });
