      c.strokeStyle = "#8a8f96"; c.lineWidth = 3; c.beginPath(); c.moveTo(X(25), Y(21.2)); c.lineTo(X(89), Y(21.2)); c.moveTo(X(25), Y(22.2)); c.lineTo(X(89), Y(22.2)); c.stroke();
      rect(54, 20, 57, 24, "#8a8f96", "#555"); txt("манифольд", 55.5, 25.5, { s: 12, c: "#555" });
