      for (var bx = 27; bx < 86; bx += 2.95) for (var by = 20; by < 29; by += 2.2) { var k2 = Math.floor(bx * 7 + by * 3) % cols.length; rect(bx, by, bx + 2.8, by + 2.1, cols[k2], "#333"); }
      rect(24.5, 21.3, 28.8, 23.3, "#e67e22", "#333"); txt("ДШ", 26.65, 22.3, { s: 11, c: "#fff", w: "700" });
      c.strokeStyle = "#555"; c.lineWidth = 3; c.beginPath(); c.moveTo(X(25), Y(20)); c.lineTo(X(25), Y(25)); c.lineTo(X(27), Y(24)); c.stroke();
      c.strokeStyle = "#e67e22"; c.lineWidth = 3; c.beginPath(); c.arc(X(1.8), Y(9.8), 11, 0, Math.PI * 2); c.stroke();
