      c.fillStyle = COL[p[5]]; c.beginPath(); c.arc(X(p[1]), Y(p[2]), 1.55 * S, 0, Math.PI * 2); c.fill(); c.strokeStyle = "#fff"; c.lineWidth = 2.5; c.stroke();
