    var key = [["k", "командный пункт"], ["a", v.kind === "cargo" ? "аварийная партия" : v.kind === "tanker" ? "шлюпочные партии" : "спасательная партия"], ["m", "машинная партия"], ["o", v.kind === "cargo" ? "средства тушения" : "обеспечение"]];
