    c.fillStyle = "#fafafa"; c.strokeStyle = "#bbb"; c.lineWidth = 1.5; c.fillRect(X(1), Y(-0.5), 98 * S, 31 * S); c.strokeRect(X(1), Y(-0.5), 98 * S, 31 * S);
    var rows = Math.ceil(v.pts.length / 2);
