      function selF(k, l, o) { return '<label class="fld"><span>' + l + '</span><select data-pf="' + k + '">' + o.map(function (x) { return '<option value="' + x[0] + '"' + (String(P[k]) === x[0] ? " selected" : "") + ">" + x[1] + "</option>"; }).join("") + "</select></label>"; }

