        function pc(x) { return (x - x0) / (x1 - x0) * 100; }
        var hy0 = 10, hy1 = Hh - 8, svg;
        if (t) rows = rows.map(function (r) { var a = -L / 2 + 0.08 * L, w = (0.8 * L) / r.length; return r.map(function (o, i) { return { s: o.s, xl: a + i * w, xr: a + (i + 1) * w }; }); });   /* танки — равными ячейками по порядку с кормы */
