    var dn1 = dn + mk.lf * Df / L + mk.tk, dk1 = dk + mk.la * Df / L + mk.tk;
    var res = { d1: d1, r1: r1, sh: sh, L: L, rho: rho, D: D, V: Vd, hy: hy, fsC: fsC, mhSt: mhSt, mhC: mhC, mh: mh, dZ: dZ, ZG: ZG, ZG1: ZG1, h0: h0, h: h,
      tg: tg, dn: dn, dk: dk, Df: Df, dm: dm, th: th, mk: mk, dn1: dn1, dk1: dk1, warn: warn };
