    for (var y = Math.ceil(Y[0] / Y[2]) * Y[2]; y <= Y[1] + 1e-9; y += Y[2]) { line(g, [[x0, py(y)], [x0 + w, py(y)]], { c: "#d6dde3", w: 1 }); txt(g, f(y, Y[3] === undefined ? 1 : Y[3]), px(Math.max(X[0], 0)) - 8, py(y), { s: 15, c: "#333", a: "right" }); }
