    rows.push(["Df — дифферент, м", f(c.Df, 3), f(lim, 3) + " ≤ Df ≤ 0 (на корму не более 1°)", c.Df <= 0.0005 && c.Df >= lim ? "соответствует" : c.Df > 0 ? "не соответствует (дифферент на нос)" : "не соответствует"]);
