    line(g, [P(0, -0.3), P(0, top)], { c: "#444", w: 1.2, dash: [14, 5, 3, 5] }); txt(g, "ДП", P(0, top)[0], P(0, top)[1] - 14, { s: 15, w: "700" });
    /* ватерлинии: ВЛ0 и ВЛ1 через точку F на ДП */
