      fr.push(["Δl = (ΣMi + Σδmh·sin θ)/Δ, м", ""].concat([10, 20, 30, 40, 50, 60, 70, 80].map(function (a, i) { return f((tot[i] + c.mhSt * Math.sin(a / R)) / c.D, 3); })));
