        if (!x.cap) { dot(g, A.px(x.a), A.py(ldAt(S, x.a)), 5, cols[i]); line(g, [[A.px(x.a), A.py(0)], [A.px(x.a), A.py(ldAt(S, x.a))]], { c: cols[i], w: 1.2, dash: [4, 4] }); }
