  function vd(extra, noSrc) {
    return function (v) {
      var b = TUS.autoFrom(v), o = { variant: v, fio: b.fio, group: b.group, n: b.n, date: "" };
      if (!noSrc) {
        var r1 = null; try { r1 = TUS.pr1(basePR1(v)); } catch (e) { }
        var g = function (x, n) { return r1 ? String(Math.round(x * Math.pow(10, n)) / Math.pow(10, n)).replace(".", ",") : ""; };
        Object.assign(o, { src: "pr1", mShip: r1 ? r1.ship.id : "bar", mD: r1 ? g(r1.D, 2) : "", mXG: r1 ? g(r1.XG, 3) : "", mYG: r1 ? g(r1.YG, 3) : "", mZG: r1 ? g(r1.ZG, 3) : "", mMh: r1 ? g(r1.dmh, 0) : "",
          mRho: r1 && r1.ship.type === "tanker" ? g(r1.c, 3) : "",
          mCargo: r1 ? r1.C.filter(function (x) { return x.m > 0; }).map(function (x) { return r1.ship.type === "tanker" ? x.name + "; " + g(x.m, 2) : x.name + "; " + g(x.m, 2) + "; " + g(x.X, 3) + "; " + g(x.Z, 3); }).join("\n") : "" });
      }
      return Object.assign(o, extra ? extra(v, SHIPS[basePR1(v).ship] || SHIPS.bar) : {});
    };
  }
