    var rows = TH.map(function (a) { return { a: a, s: sin(a), C: man ? null : U.fn(a), Clo: man ? null : UNI.C[UNI.dw.indexOf(U.lo)][a / 5], Chi: man ? null : UNI.C[UNI.dw.indexOf(U.hi)][a / 5], ray: h1 * sin(a), l0: l0(a), g: dlg(a), v: dlv(a), la: la(a) }; });
