        rows: r.cg.map(function (x) { return [x.name, f(x.sp.V, 2), f(x.V, 2), f(x.pct, 1), f(x.m, 2), f(x.X, 2), f(x.Y, 2), f(x.Z, 2), f(x.sp.Pmax, 0), x.overP || x.overV || !x.sp.grain ? "нельзя" : "≤ Pmax"]; })
