  /* ---------- схема размещения груза (профиль судна) ---------- */
  function clipBelow(pts, z) {   /* часть многоугольника ниже горизонтали z */
    var out = [];
    for (var i = 0; i < pts.length; i++) {
      var a = pts[i], b = pts[(i + 1) % pts.length], ia = a[1] <= z, ib = b[1] <= z;
      if (ia) out.push(a);
      if (ia !== ib) { var t = (z - a[1]) / (b[1] - a[1]); out.push([a[0] + t * (b[0] - a[0]), z]); }
    }
    return out;
  }
  function bounds(pts) { var xs = pts.map(function (p) { return p[0]; }), zs = pts.map(function (p) { return p[1]; }); return [Math.min.apply(null, xs), Math.max.apply(null, xs), Math.min.apply(null, zs), Math.max.apply(null, zs)]; }
  function drawPlan(cvs, r) {
    var sh = r.sh, kx = 8, ky = 13, x0 = 70, W = 1520, zTop = 23, H = 420, g = G.cv(cvs, W, H), yB = 34 + zTop * ky;
    cvs._cm = 24;   /* в отчёте — на альбомном листе */
    function P(fr, z) { return [x0 + (FR(sh, fr) - FR(sh, -8)) * kx, yB - z * ky]; }
    function poly(pts, o) { G.line(g, pts.map(function (p) { return P(p[0], p[1]); }), o); }
    /* корпус */
    poly(sh.hull, { close: true, w: 2.2, fill: "#fbfbfb" });
    sh.hatches.forEach(function (h) { poly([[h[0], h[2]], [h[0], h[2] + 1.9], [h[1], h[2] + 1.9], [h[1], h[2]]], { w: 1.6 }); });
    var dk = sh.decks;
    poly([[dk.ib[0], dk.ib[2]], [dk.ib[1], dk.ib[2]]], { w: 1, c: "#666", dash: [6, 4] });
    /* прочие помещения */
    sh.other.forEach(function (q) { poly(q[1], { close: true, w: 1, c: "#888", dash: [5, 4] }); var bb = bounds(q[1]), a = P((bb[0] + bb[1]) / 2, (bb[2] + bb[3]) / 2); G.txt(g, q[0], a[0], a[1], { s: 13, c: "#666" }); });
    /* грузовые помещения */
    var byId = {}; r.cg.forEach(function (x) { byId[x.id] = x; });
    sh.spaces.forEach(function (s) {
      var gq = s.geo, x = byId[s.id], bb = bounds(gq);
      if (x) {
        var zl = x.full ? bb[3] : Math.min(bb[3], s.bot + (x.H !== null ? x.H : (bb[3] - s.bot) * x.pct / 100));
        var fp = x.full ? gq : clipBelow(gq, zl);
        poly(fp, { close: true, fill: "#f2d98a", nostroke: true });
        if (!x.full) { var cl = fp.filter(function (q) { return Math.abs(q[1] - zl) < 1e-6; }); if (cl.length >= 2) poly(cl, { c: "#b07a10", w: 1.6 }); }
      }
      poly(gq, { close: true, w: 1.8, c: x ? "#8a5a00" : "#555" });
      var cx = (P(bb[0], 0)[0] + P(bb[1], 0)[0]) / 2, cy = (P(0, bb[2])[1] + P(0, bb[3])[1]) / 2, wpx = P(bb[1], 0)[0] - P(bb[0], 0)[0], nm = s.name.replace(/\s*\(.*\)/, ""), short = nm.replace("Твиндек", "Твд").replace("Трюм", "Тр.");
      if (x) {
        G.txt(g, (wpx > 150 ? nm : short) + ": " + f(x.m, 1) + " т", cx, cy - 9, { s: 14, w: "700", c: "#111" });
        G.txt(g, f(x.pct, 1) + " %,  V = " + f(x.V, 1) + " м³", cx, cy + 10, { s: 13, c: "#333" });
      } else G.txt(g, short, cx, cy, { s: 12, c: "#777" });
    });
    /* шкала шпангоутов, перпендикуляры, мидель */
    var yb = yB + 20;
    G.line(g, [[P(-8, 0)[0], yb], [P(205, 0)[0], yb]], { w: 1, c: "#444" });
    for (var fr = 0; fr <= 200; fr += 10) { var p = P(fr, 0); G.line(g, [[p[0], yb - 4], [p[0], yb + 4]], { w: 1, c: "#444" }); G.txt(g, String(fr), p[0], yb + 15, { s: 12, c: "#444" }); }
    G.txt(g, "шп.", P(-8, 0)[0] - 6, yb + 15, { s: 12, a: "right", c: "#444" });
    G.line(g, [P(-12, 0), P(212, 0)], { w: 1, c: "#444", dash: [12, 4, 2, 4] }); G.txt(g, "ОП", P(212, 0)[0] + 6, yB, { s: 13, a: "left", c: "#444" });
    [[-79.8, "КП"], [0, "⊗ мидель"], [79.8, "НП"]].forEach(function (q) {
      var px = x0 + (q[0] - FR(sh, -8)) * kx, top = P(0, 21.5)[1];
      G.line(g, [[px, yB + 10], [px, yB - 4]], { w: 1.4, c: "#1b6fb3" }); G.line(g, [[px, top], [px, top + 22]], { w: 1.4, c: "#1b6fb3" });
      G.txt(g, q[1], px, top - 10, { s: 14, c: "#1b6fb3", w: "700" });
    });
    G.txt(g, "Нос — справа. Жёлтым — груз (уровень зерна по таблицам «Гидростатические элементы отсеков»); вертикальный масштаб увеличен в " + f(ky / kx, 2) + " раза", W / 2, H - 12, { s: 13, c: "#333" });
  }

