        function lab(i) { var l = m.labels ? m.labels[i - 1] : null; return l ? (/^\d/.test(l) ? "стр. " + l : l) : (m.id === "nav-video" ? "кадр " + i : "стр. " + i); }
        function show(i) { cur = Math.max(1, Math.min(m.n, i)); v.querySelector("img").src = "m/" + m.id + "/" + pad(cur) + ".jpg"; v.querySelector("#mvNo").textContent = lab(cur) + " / " + m.n; v.querySelector(".vscroll").scrollTop = 0; v.hidden = false; }
        for (var i = 1; i <= m.n; i++) (function (i) {
          var b = el("button", { type: "button", class: "pg" });
          b.innerHTML = '<img loading="lazy" alt="' + lab(i) + '" src="m/' + m.id + "/" + pad(i) + '.jpg"><span>' + lab(i) + "</span>";
          b.addEventListener("click", function () { show(i); });
          box.appendChild(b);
        })(i);
        v.querySelector(".vclose").addEventListener("click", function () { v.hidden = true; });
        v.querySelector("#mvPrev").addEventListener("click", function () { show(cur - 1); });
        v.querySelector("#mvNext").addEventListener("click", function () { show(cur + 1); });
