      if (isFinite(r.II) && isFinite(r.I)) {
        var dn = r.II - r.I; if (dn < 0) dn += 10000; r.n = Math.round(dn / tt * 100) / 100; r.W = Math.round((a + b * r.n) * 10) / 10; r.mc = true;
      } else if (isFinite(r.W0)) { r.W = r.W0; r.mc = false; }
