    [[xa, xb], [xb, xa]].forEach(function (p) { var s = p[1] > p[0] ? 1 : -1; c.beginPath(); c.moveTo(p[0], y); c.lineTo(p[0] + 13 * s, y - 5); c.lineTo(p[0] + 13 * s, y + 5); c.closePath(); c.fill(); });
